#if DEBUG
/// Demo-only page that presents a sheet straight away, so sheets can be
/// opened for screenshots with DUBBL_DEMO_OPEN=page:<debug path>.
struct SalesDebugSheetPage<Sheet: View>: View {
    @ViewBuilder var sheet: () -> Sheet
    @State private var shown = false

    var body: some View {
        DTheme.shell
            .ignoresSafeArea()
            .task { shown = true }
            .sheet(isPresented: $shown) { sheet() }
    }
}
#endif
